11:     { id: 'relay', name: 'Listening post', icon: '⌁', desc: 'A second ear in the dark · +0.4 drift/sec', base: 15, effect: 'rate', amount: .4, unlock: 0 },
12:     { id: 'choir', name: 'The night choir', icon: '♬', desc: 'Old radios singing together · +2 drift/sec', base: 90, effect: 'rate', amount: 2, unlock: 40 },
13:     { id: 'mirror', name: 'Moon mirror', icon: '◒', desc: 'Focus the light · +2 pulse strength', base: 240, effect: 'click', amount: 2, unlock: 150 },
14:     { id: 'array', name: 'Deep-space array', icon: '✧', desc: 'Listen between the stars · +12 drift/sec', base: 1100, effect: 'rate', amount: 12, unlock: 700 }
15:   ];
16:   const missions = [
17:     { title: 'A voice in the dark', description: 'Send 12 pulses to make the old dish hum.', type: 'pulses', target: 12, reward: 12 },
18:     { title: 'A second pair of ears', description: 'Build 3 listening posts for the station.', type: 'relay', target: 3, reward: 55 },
19:     { title: 'Keep the porch light on', description: 'Gather 250 signal. Someone may be watching.', type: 'lifetime', target: 250, reward: 90 },
20:     { title: 'Let the choir answer', description: 'Build 2 night choirs and fill the silence.', type: 'choir', target: 2, reward: 180 },
21:     { title: 'Reflect what remains', description: 'Build 2 moon mirrors to focus your pulse.', type: 'mirror', target: 2, reward: 400 },
22:     { title: 'A signal beyond the moon', description: 'Gather 2,000 signal. The reply is getting closer.', type: 'lifetime', target: 2000, reward: 900 },
23:     { title: 'The sky has a voice', description: 'Build 2 deep-space arrays. Find out who it belongs to.', type: 'array', target: 2, reward: 2200 }
24:   ];
25:   const fresh = () => ({ signal: 0, lifetime: 0, echoes: 0, upgrades: { relay: 0, choir: 0, mirror: 0, array: 0 }, pulses: 0, mission: 0, missionClaimed: -1, frequency: 'warm', phase: 0, phaseAt: Date.now(), lastSave: Date.now(), fragments: [], sound: false });
26:   let state = fresh();
27:   try {
28:     const saved = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null');
29:     if (saved && typeof saved === 'object') {
30:       state = { ...fresh(), ...saved, upgrades: { ...fresh().upgrades, ...(saved.upgrades || {}) }, fragments: Array.isArray(saved.fragments) ? saved.fragments.slice(-5) : [] };
31:       state.signal = Math.max(0, Number(state.signal) || 0);
32:       state.lifetime = Math.max(state.signal, Number(state.lifetime) || 0);
33:       state.echoes = Math.max(0, Math.floor(Number(state.echoes) || 0));
34:       state.mission = Math.max(0, Math.floor(Number(state.mission) || 0));
35:       state.pulses = Math.max(0, Math.floor(Number(state.pulses) || 0));
36:       state.phase = Math.abs(Math.floor(Number(state.phase) || 0)) % 3;
37:       if (!frequencies.includes(state.frequency)) state.frequency = 'warm';
38:       Object.keys(state.upgrades).forEach(id => state.upgrades[id] = Math.max(0, Math.floor(Number(state.upgrades[id]) || 0)));
39:       const away = Math.min(8 * 60 * 60, Math.max(0, (Date.now() - (Number(state.lastSave) || Date.now())) / 1000));
40:       const drift = getBaseRate() * away;
41:       if (drift > 1) { state.signal += drift; state.lifetime += drift; setTimeout(() => toast(`Welcome back. ${format(drift)} signal gathered while you were away.`), 500); }
42:       if (Date.now() - (Number(state.phaseAt) || Date.now()) >= 60000) state.phaseAt = Date.now();
43:     }
44:   } catch (_) { state = fresh(); }
